<style lang="scss" scoped>
.contact-wrapper {
    display: flex;
    flex-direction: column;
    gap: 2rem;
    margin-top: 3.5rem;



    .contact-info {
        display: flex;
        align-items: center;
        gap: 2rem;
        cursor: pointer;

        @include media-max(tablet) {
            justify-content: center;

        }



        .text {
            // font-size: 0.9rem;
        }

        @include media-max(phone) {
            flex-direction: column;
            gap: 1rem;

            .text {
                text-align: center;
            }
        }


    }
}

.socials {
    margin-top: 8rem;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 2rem;

    .social-box {
        display: block;
        width: 5rem;
        height: 5rem;
        padding: 1rem;
        border-radius: 16px;
        display: flex;
        justify-content: center;
        align-items: center;
        background-color: $light-blue;
        cursor: pointer;

        >svg {
            width: 100%;
            height: 100%;
        }
    }

}
</style>
